import spidev

# SPI setup
spi = spidev.SpiDev()
spi.open(0, 0)
spi.max_speed_hz = 1000000
spi.mode = 0
spi.lsbfirst = False

def validate_channel(channel):
    if channel < 0 or channel > 7:
        return False
    return True

def read_adc(channel):
    if not validate_channel(channel):
        return -1

    adc_command = 0b11000000 | (channel << 3)

    try:
        reply = spi.xfer2([adc_command, 0x00])
    except Exception as e:
        print(f"SPI transfer failure: {str(e)}")
        spi.close()
        return -1

    adc_out = ((reply[0] & 0x03) << 8) | reply[1]

    return adc_out / 4095.0 if reply else -1

def close_spi():
    spi.close()

def main():
    channel = 0
    adc_val = read_adc(channel)

    if adc_val == -1:
        print(f"Error reading ADC channel {channel}")
    else:
        print(f"ADC channel {channel}: {adc_val}")

    close_spi()

if __name__ == "__main__":
    main()

