class MCP3208:
    def __init__(self, bus=0, device=0):
        self.bus = bus
        self.device = device
        self.spi = spidev.SpiDev()

    def open(self):
        self.spi.open(self.bus, self.device)
        self.spi.max_speed_hz = 1000000  # 1MHz

    def close(self):
        self.spi.close()

    def read(self, channel):
        if channel < 0 or channel > 7:
            raise ValueError("Channel must be between 0 and 7")

        # Start bit = 1, single-ended mode = 0, channel = 0-7
        adc_command = [1, (8 + channel) << 4, 0]

        try:
            reply = self.spi.xfer2(adc_command)
        except spidev.SpiError as e:
            print(f"SPI error: {e}")
            return None

        # Extract the 12-bit value from the reply
        adc_out = ((reply[1] & 3) << 8) + reply[2]

        return adc_out


