class ADS1115:
    def __init__(self, address=0x48, bus=None):
        if bus is None:
            bus = busio.I2C(board.SCL, board.SDA)
        self.ads = ADS1115(bus)
        self.ads.address = address
        self.ads.high_threshold_enabled = False
        self.ads.low_threshold_enabled = False
        self.ads.data_rate = 860  # 860 samples per second
        self.ads.mode = ADS1115.Mode.CONTINUOUS
        self.ads.programmable_gain = ADS1115.ProgrammableGain.PGA_1

    def read(self, channel, pga):
        if channel not in range(4):
            raise ValueError("Channel must be 0-3")
        if pga not in [6144, 4096, 2048, 1024, 512, 256]:
            raise ValueError("PGA must be 6144, 4096, 2048, 1024, 512, or 256")
        self.ads.programmable_gain = pga
        time.sleep(0.0001)  # Wait for PGA to settle
        try:
            value = self.ads.read(channel)
            time.sleep(0.01)  # Wait for conversion to complete
            value = self.ads.read(channel)
            return value * 0.0005  # Convert to millivolts
        except Exception as e:
            raise IOError("Failed to read from ADC") from e

    def __del__(self):
        try:
            self.ads.close()
        except Exception as e:
            print("Failed to close I2C bus:", e)

