def degrees_decimal_to_dms(degrees_decimal):
    if not isinstance(degrees_decimal, (int, float)):
        raise ValueError("degrees_decimal must be a real number")

    degrees = int(degrees_decimal)
    minutes_decimal = (degrees_decimal - degrees) * 60
    minutes = int(minutes_decimal)
    seconds = (minutes_decimal - minutes) * 60

    return (degrees, minutes, seconds)

def number_to_exif_rational(number):
    if not isinstance(number, (int, float)):
        raise ValueError("number must be a real number")

    numerator = int(number * 1000)
    denominator = 1000

    if not isinstance(numerator, int) or not isinstance(denominator, int):
        raise TypeError("numerator and denominator must be integers")

    return (numerator, denominator)

def get_gps_data():
    while True:
        line = ser.readline().decode('utf-8').strip()
        if line.startswith('$GPGGA'):
            data = line.split(',')
            if data[3] != '' and data[5] != '':
                latitude = float(data[3])
                longitude = float(data[5])
                return (latitude, longitude)

def set_exif_metadata(image_path, latitude, longitude):
    exif_data = {
        ExifTags.GPSInfo: {
            ExifTags.GPSInfoTag.GPSLatitude: degrees_decimal_to_dms(latitude),
            ExifTags.GPSInfoTag.GPSLatitudeRef: 'N' if latitude >= 0 else 'S',
            ExifTags.GPSInfoTag.GPSLongitude: degrees_decimal_to_dms(longitude),
            ExifTags.GPSInfoTag.GPSLongitudeRef: 'E' if longitude >= 0 else 'W',
        }
    }

    image = Image.open(image_path)
    exif = image._getexif()
    if exif is None:
        exif = {}
    exif.update(exif_data)
    image._setexif(exif)
    image.save(image_path)

# Example usage
latitude, longitude = get_gps_data()
set_exif_metadata('image.jpg', latitude, longitude)
```

This program first opens the serial port to communicate with the GPS module. It then defines two utility functions to convert decimal degrees to degrees, minutes, seconds (DMS) and any real number to a rational value suitable for EXIF metadata. The `get_gps_data` function reads from the serial port until it receives a line starting with '$GPGGA', which indicates a fix has been received. It then returns the latitude and longitude as floats. The `set_exif_metadata` function sets the EXIF GPS metadata for an image.

Please note that you need to install the `pyserial` and `Pillow` libraries before running this program. You can install them using pip:

```bash
pip install pyserial Pillow
```

Also, please replace `'image.jpg'` with the path to your image file.

