LOW_LIGHT_THRESHOLD = 300
HIGH_TEMP_THRESHOLD = 35
HIGH_PI_TEMP_THRESHOLD = 75

light_sensor = LightSensor(17)
temp_sensor = Temperature()

def get_pi_temp():
    try:
        output = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, timeout=1)
        temp_str = output.stdout.split('=')[1].split("'")[0]
        return float(temp_str)
    except (subprocess.SubprocessError, IndexError, ValueError):
        print("Failed to read Pi temperature")
        return None

def simulate_light():
    while True:
        try:
            lux = light_sensor.lux
            if lux < LOW_LIGHT_THRESHOLD:
                print(f"WARNING: Light level is too low ({lux} lux)")
            voltage = 11.5 + (lux - 300) / 100 * 1.0
            current = 1.5 + (lux - 300) / 100 * 0.5
            return lux, voltage, current
        except Exception as e:
            print(f"Error simulating light: {e}")
            return 0, 0, 0

def simulate_temp():
    while True:
        try:
            temp = temp_sensor.temperature
            if temp > HIGH_TEMP_THRESHOLD:
                print(f"WARNING: Temperature is too high ({temp}°C)")
            return temp
        except Exception as e:
            print(f"Error simulating temperature: {e}")
            return 0

def log_data(lux, temp, voltage, current, pi_temp):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{timestamp} LUX: {lux} VOLTAGE: {voltage} CURRENT: {current} TEMP: {temp} PI_TEMP: {pi_temp}")

def main():
    pi_temp_thread = Thread(target=get_pi_temp)
    light_thread = Thread(target=simulate_light)
    temp_thread = Thread(target=simulate_temp)

    pi_temp_thread.start()
    light_thread.start()
    temp_thread.start()

    try:
        while True:
            lux, voltage, current = light_thread.join()
            temp = temp_thread.join()
            pi_temp = pi_temp_thread.join()
            if pi_temp > HIGH_PI_TEMP_THRESHOLD:
                print("CRITICAL WARNING: Pi temperature is too high, shutting down system")
                break
            log_data(lux, temp, voltage, current, pi_temp)
            time.sleep(5)
    except KeyboardInterrupt:
        print("Gracefully terminating")
    finally:
        light_sensor.close()

if __name__ == "__main__":
    main()

