import smbus2
import time
import logging
from crc8 import Crc8

class DHT20:
    POWER_STABILIZATION_TIME = 0.5
    STATUS_REGISTER = 0x71
    STATUS_MASK = 0x80
    DATA_REGISTER = 0x31
    POLYNOMIAL = 0x31
    INITIAL_VALUE = 0xFF
    TIMEOUT = 0.1
    RETRY_DELAY = 0.2
    MAX_RETRIES = 5

    def __init__(self, bus_number=1):
        self.bus = smbus2.SMBus(bus_number)
        time.sleep(self.POWER_STABILIZATION_TIME)
        if not self.verify_status():
            logging.error("Status check failed")
            self.bus.close()
            raise Exception("Status check failed")

    def __del__(self):
        self.cleanup()

    def verify_status(self):
        try:
            status = self.bus.read_byte_data(self.STATUS_REGISTER)
            return (status & self.STATUS_MASK) == 0
        except Exception as e:
            logging.error(f"Error verifying status: {e}")
            return False

    def read_data(self):
        for i in range(self.MAX_RETRIES):
            if not self.verify_status():
                logging.warning(f"Status check failed, retry {i+1}")
                time.sleep(self.RETRY_DELAY)
                continue
            try:
                data = self.bus.read_i2c_block_data(self.DATA_REGISTER, 7)
                raw_humidity = (data[1] << 12) | (data[2] << 4)
                raw_temperature = (data[2] >> 4) | (data[3] << 12)
                crc = Crc8(self.POLYNOMIAL, self.INITIAL_VALUE)
                crc.update(data[:6])
                crc_error = crc.crc != data[6]
                return (raw_temperature, raw_humidity, crc_error)
            except Exception as e:
                logging.error(f"Error reading data: {e}")
                time.sleep(self.RETRY_DELAY)
        return (None, None, True)

    def cleanup(self):
        self.bus.close()

