        try:
            self.bus = smbus2.SMBus(1)
            self.verify_sensor()
        except Exception as e:
            logging.error(f"Error opening I2C bus: {e}")
            self.bus = None

    def verify_sensor(self):
        status = self.bus.read_byte_data(self.I2C_ADDR, self.STATUS_REG)
        if status != 0x18:
            raise Exception(f"Sensor verification failed: {status}")

    def measure(self):
        if self.bus is None:
            return None, None, True

        try:
            self.bus.write_byte(self.I2C_ADDR, self.DATA_REG)

            for _ in range(100):  # 100 * 10ms = 1000ms = 1s timeout
                status = self.bus.read_byte_data(self.I2C_ADDR, self.STATUS_REG)
                if status & 0x80:
                    break
                time.sleep(0.01)
            else:
                return None, None, True

            data = self.bus.read_i2c_block_data(self.I2C_ADDR, self.DATA_REG, 6)

            raw_humidity = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
            raw_temperature = (data[2] & 0x0F) | (data[3] << 4) | (data[4] << 12)
            crc = data[5]

            crc_calc = self.calculate_crc(raw_humidity, raw_temperature)
            if crc != crc_calc:
                raise Exception(f"CRC error: {crc} != {crc_calc}")

            humidity = raw_humidity * 100.0 / 0x1000000
            temperature = (raw_temperature * 200.0 / 0x1000000) - 50

            return temperature, humidity, False
        except Exception as e:
            logging.error(f"Measurement error: {e}")
            return None, None, True

