        data = (humidity >> 16) & 0xFF, (humidity >> 8) & 0xFF, humidity & 0xFF, (temperature >> 16) & 0xFF, (temperature >> 8) & 0xFF, temperature & 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ self.CRC_POLYNOMIAL
                else:
                    crc <<= 1
        return crc

