import time
import logging

# Set up logging
logging.basicConfig(filename='sensor_errors.log', level=logging.ERROR)

# Set up serial port
ser = None
while ser is None:
    try:
        ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
    except serial.SerialException as e:
        logging.error(f"Failed to initialize serial port: {e}")
        time.sleep(1)  # Wait for one second before trying again

# Main loop
try:
    while True:
        try:
            line = ser.readline().decode().strip()
            if line:
                try:
                    temperature, humidity = map(float, line.split(','))
                    if temperature > 30.0 or humidity > 70.0:
                        logging.warning(f"Alert: Temperature: {temperature}C, Humidity: {humidity}%")
                    else:
                        print(f"Temperature: {temperature}C, Humidity: {humidity}%")
                except ValueError as e:
                    logging.error(f"Malformed line: {e}")
            else:
                logging.error("Sensor absent timeout")
        except serial.SerialException as e:
            logging.error(f"Transient I/O error: {e}")

        time.sleep(1)  # Wait for one second before trying again

except KeyboardInterrupt:
    pass

finally:
    if ser:
        ser.close()

