import time
import threading
from gpiozero import DOG
from paho.mqtt import client as mqtt_client

# Initialize the DOG device
dog = DOG()

# Initialize the MQTT client
client = mqtt_client.Client()

# Initialize the log file
log_file = None

# Initialize the receive thread
receive_thread = None

# Initialize the lock
lock = threading.Lock()

# Function to handle the start command
def handle_start(filename):
    global log_file, receive_thread
    try:
        # Create the log file
        log_file = open(filename, 'w')

        # Start the receive thread
        receive_thread = threading.Thread(target=receive)
        receive_thread.start()
    except Exception as e:
        print(f"Error: {e}")

# Function to handle the stop command
def handle_stop():
    global receive_thread
    try:
        # Stop the receive thread
        if receive_thread is not None:
            receive_thread.join()
            receive_thread = None
    except Exception as e:
        print(f"Error: {e}")

# Function to handle the receive command
def receive():
    while True:
        try:
            # Receive data from the DOG device
            data = dog.receive()

            # Write the data to the log file
            with lock:
                log_file.write(f"{data}\n")
                log_file.flush()
        except Exception as e:
            print(f"Error: {e}")

        # Sleep for 0.1 seconds
        time.sleep(0.1)

# Function to handle the help command
def handle_help(command=None):
    if command is None:
        print("Commands: start <filename>, stop, help [command], display, send <data>, write <data>, exit")
    else:
        print(f"Unknown command: {command}")

# Function to handle the display command
def handle_display():
    try:
        # Print the contents of the log file
        with lock:
            print(log_file.read())
    except Exception as e:
        print(f"Error: {e}")

# Function to handle the send command
def handle_send(data):
    try:
        # Send data via the DOG device
        dog.send(data)
    except Exception as e:
        print(f"Error: {e}")

# Function to handle the write command
def handle_write(data):
    try:
        # Write data to the log file
        with lock:
            log_file.write(f"{data}\n")
            log_file.flush()
    except Exception as e:
        print(f"Error: {e}")

# Function to handle the exit command
def handle_exit():
    global log_file, receive_thread
    try:
        # Stop the receive thread
        handle_stop()

        # Close the log file
        log_file.close()

        # Exit the program
        exit(0)
    except Exception as e:
        print(f"Error: {e}")

# Main function
def main():
    while True:
        # Get the command from the user
        command = input("> ")

        # Split the command into the command and the arguments
        parts = command.split()

        # Handle the command
        if len(parts) == 0:
            continue

        if parts[0] == "start":
            handle_start(parts[1])
        elif parts[0] == "stop":
            handle_stop()
        elif parts[0] == "help":
            handle_help(parts[1] if len(parts) > 1 else None)
        elif parts[0] == "display":
            handle_display()
        elif parts[0] == "send":
            handle_send(" ".join(parts[1:]))
        elif parts[0] == "write":
            handle_write(" ".join(parts[1:]))
        elif parts[0] == "exit":
            handle_exit()
        else:
            print(f"Unknown command: {parts[0]}")

# Call the main function
if __name__ == "__main__":
    main()

