            log_file.flush()
    except Exception as e:
        print(f"Error: {e}")

# Function to handle the exit command
def handle_exit():
    global log_file, receive_thread
    try:
        # Stop the receive thread
        handle_stop()

        # Close the log file
        log_file.close()

        # Exit the program
        exit(0)
    except Exception as e:
        print(f"Error: {e}")

# Main function
