import gpiozero
import time
import signal
import zmq
import logging

class PIDHandler:
    def __init__(self):
        self.pwm_pin = gpiozero.PWMOutputDevice(pin=18, frequency=1000, initial_value=0.0, active_high=True)
        self.digital_pin = gpiozero.DigitalOutputDevice(pin=15, active_high=True)
        self.pwm_flag = False
        self.global_err_state = False
        self.last_msg = time.time()
        self.context = zmq.Context()
        self.socket = self.context.socket(zmq.SUB)
        self.socket.connect("tcp://localhost:5555")
        self.socket.setsockopt(zmq.SUBSCRIBE, b"")

        # Set up logging
        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger(__name__)

        # Set up signal handlers
        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def update_error_output(self):
        if self.global_err_state:
            self.set_error_output(True)
        else:
            self.set_error_output(False)

    def set_error_output(self, state):
        try:
            if self.pwm_flag:
                self.pwm_pin.value = state
            else:
                self.digital_pin.value = state
        except gpiozero.exc.PinInitializationError as e:
            self.logger.error(f"Failed to initialize GPIO pin: {e}")

    def handle_message(self):
        try:
            msg = self.socket.recv(zmq.NOBLOCK)
            if msg:
                self.last_msg = time.time()
                # Process the message here
            else:
                if time.time() - self.last_msg > 20:
                    self.set_error_output(True)
        except zmq.error.ZMQError as e:
            self.logger.error(f"Failed to receive message: {e}")

    def cleanup(self, signum, frame):
        self.pwm_pin.close()
        self.digital_pin.close()
        self.socket.close()
        self.context.term()
        self.logger.info(f"Cleaned up on signal {signum}")

if __name__ == "__main__":
    handler = PIDHandler()
    while True:
        handler.handle_message()
        time.sleep(0.1)

