import RPi.GPIO as GPIO
import time
import signal
import logging

class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.counter = 0

        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(self.dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        GPIO.add_event_detect(self.clk_pin, GPIO.BOTH, callback=self.clk_rising_falling, bouncetime=20)
        GPIO.add_event_detect(self.dt_pin, GPIO.BOTH, callback=self.dt_rising_falling, bouncetime=20)

    def clk_rising_falling(self, channel):
        if GPIO.input(self.clk_pin):
            self.counter += 1
        else:
            self.counter -= 1
        self.invoke_callback()

    def dt_rising_falling(self, channel):
        if GPIO.input(self.dt_pin):
            self.counter -= 1
        else:
            self.counter += 1
        self.invoke_callback()

    def invoke_callback(self):
        if callable(self.callback):
            try:
                self.callback(self.counter)
            except Exception as e:
                logging.error(f"Error invoking callback: {e}")

    def cleanup(self):
        GPIO.remove_event_detect(self.clk_pin)
        GPIO.remove_event_detect(self.dt_pin)
        GPIO.cleanup([self.clk_pin, self.dt_pin])

def main():
    def print_counter(counter):
        print(f"Counter: {counter}")

    try:
        encoder = RotaryEncoder(17, 18, callback=print_counter)
        while True:
            time.sleep(1)
    except (IOError, RuntimeError) as e:
        logging.error(f"Error: {e}")
    except KeyboardInterrupt:
        encoder.cleanup()

if __name__ == "__main__":
    main()

