class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None, debounce_interval=0.005):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.debounce_interval = debounce_interval
        self.last_clk_state = None
        self.counter = 0

        if callback is not None and not callable(callback):
            raise ValueError("Callback must be callable")
        self.callback = callback

        GPIO.setmode(GPIO.BCM)
        GPIO.setup(clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        GPIO.add_event_detect(clk_pin, GPIO.BOTH, callback=self.clk_callback, bouncetime=int(debounce_interval * 1000))

    def clk_callback(self, channel):
        current_clk_state = GPIO.input(self.clk_pin)
        if current_clk_state != self.last_clk_state:
            current_dt_state = GPIO.input(self.dt_pin)
            if current_dt_state != current_clk_state:
                self.counter += 1
            else:
                self.counter -= 1

            if self.callback is not None:
                try:
                    self.callback(self.counter)
                except Exception as e:
                    print(f"Error in callback: {e}")

            self.last_clk_state = current_clk_state

    def cleanup(self):
        GPIO.remove_event_detect(self.clk_pin)
        GPIO.cleanup([self.clk_pin, self.dt_pin])


