class MotorError(Exception):
    pass

class Motor:
    def __init__(self, driver, pin):
        try:
            self.motor = PWMOutputDevice(pin, True, 0, 1000)
            self.driver = driver
        except Exception as e:
            raise MotorError("Failed to initialise motor: {}".format(e))

    def set_frequency(self, freq):
        try:
            self.motor.frequency = freq
            return self.driver.setPWMFreq(self.motor.pin, freq)
        except Exception as e:
            raise MotorError("Failed to set frequency: {}".format(e))

    def set_duty_cycle(self, duty):
        if duty < 0 or duty > 255:
            raise MotorError("Duty cycle must be between 0 and 255")
        try:
            self.motor.value = duty / 255.0
            return self.driver.setPWM(self.motor.pin, 0, int(duty * 4096 / 255))
        except Exception as e:
            raise MotorError("Failed to set duty cycle: {}".format(e))

    def stop(self):
        self.set_duty_cycle(0)

    def close(self):
        self.stop()
        self.motor.close()

    def __del__(self):
        self.close()

