                logging.warning(f"No response error: {str(e)}")
            except minimalmodbus.SerialException as e:
                logging.warning(f"Serial error: {str(e)}")
        else:
            logging.warning(f"Not connected to {self.port}")

    def write_register(self, address, value, functioncode='w'):
