import logging
from gpiozero import AutomationHAT, OutputDevice

class GarageDoor:
    def __init__(self, state_pin=1, relay_pin='relay.one'):
        try:
            self.hat = AutomationHAT()
            self.state_pin = self.hat.input[state_pin]
            self.relay = OutputDevice(relay_pin)
        except Exception as e:
            logging.error(f"Error initializing Automation HAT: {e}")
            exit(1)

        self.logger = logging.getLogger('GarageDoor')
        self.logger.setLevel(logging.INFO)
        handler = logging.StreamHandler()
        handler.setFormatter(logging.Formatter('%(asctime)s - %(message)s'))
        self.logger.addHandler(handler)

    def read_state(self):
        try:
            state = self.state_pin.value
            if state is None:
                raise ValueError("Unexpected value read from state pin")
            return state
        except Exception as e:
            self.logger.error(f"Error reading state: {e}")
            return None

    def open_door(self):
        try:
            self.relay.on()
            time.sleep(0.5)
            self.relay.off()
        except Exception as e:
            self.logger.error(f"Error opening door: {e}")

    def close_door(self):
        try:
            self.relay.on()
            time.sleep(0.5)
            self.relay.off()
        except Exception as e:
            self.logger.error(f"Error closing door: {e}")

    def toggle_door(self):
        state = self.read_state()
        if state is None:
            return

        if state == 1:
            self.logger.info("Door is open, closing...")
            self.close_door()
        else:
            self.logger.info("Door is closed, opening...")
            self.open_door()

def signal_handler(signal, frame):
    My_Garage.relay.off()
    exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    My_Garage = GarageDoor()
    My_Garage.toggle_door()

