        self.logger = logging.getLogger('ModbusServoController')
        self.client = None
        try:
            self.client = ModbusClient(method='rtu', port=port, baudrate=baudrate, timeout=1)
            self.client.connect()
        except serial.SerialException as e:
            self.logger.error(f"Failed to open serial port: {e}")
            exit(1)

        # Setup signal handlers
        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def move_servo(self, address, position):
        if not 0 <= address <= 255:
            return "Invalid address. Must be between 0 and 255."
        if not 0 <= position <= 100:
            return "Invalid position. Must be between 0 and 100."

        try:
            self.client.write_register(address, position)
            return "Success"
        except Exception as e:
            self.logger.error(f"Failed to move servo: {e}")
            return "Failed to move servo"

    def read_servo(self, address):
        if not 0 <= address <= 255:
            return "Invalid address. Must be between 0 and 255.", None

        try:
            result = self.client.read_holding_registers(address, 1)
            return "Success", result.registers[0]
        except Exception as e:
            self.logger.error(f"Failed to read servo: {e}")
            return "Failed to read servo", None

    def cleanup(self, signum, frame):
        if self.client:
            self.client.close()
        exit(0)


if __name__ == "__main__":
    controller = ModbusServoController()
    if controller.client:
        print(controller.move_servo(1, 50))
        print(controller.read_servo(1))
        controller.cleanup(None, None)
