from gpiozero import OutputDevice
import json
import signal

app = Flask(__name__)
relay = OutputDevice(23)

@app.route('/relay', methods=['POST'])
def change_relay_state():
    if not request.is_json:
        return jsonify({"error": "Invalid request"}), 400

    data = request.get_json()

    if 'state' not in data:
        return jsonify({"error": "Invalid request"}), 400

    state = data['state']

    if state not in ['on', 'off']:
        return jsonify({"error": "Invalid request"}), 400

    try:
        if state == 'on':
            relay.on()
        else:
            relay.off()
    except Exception as e:
        return jsonify({"error": str(e)}), 500

    return jsonify({"status": "Relay state changed"}), 200

def signal_handler(signal, frame):
    relay.close()
    exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    app.run(host='0.0.0.0', port=5000)

import time
import signal
import datetime
from gpiozero import OutputDevice

class Solenoid:
    def __init__(self, gpio_pin):
        self.relay = OutputDevice(gpio_pin)
        self.pulse_count = 0

    def validate_relay(self):
        if self.relay.is_active:
            raise Exception("Relay is already active")

    def activate_relay(self):
        self.validate_relay()
        self.relay.on()
        time.sleep(0.4)
        self.relay.off()
        self.pulse_count += 1
        print(f"{datetime.datetime.now()} - Pulse {self.pulse_count}")

    def schedule_pulses(self):
        for _ in range(3):
            self.activate_relay()
            time.sleep(1)

    def handle_exit(self, signum, frame):
        self.relay.close()
        print("Exiting program")
        exit(0)

def main():
    solenoid = Solenoid(24)

    # Set up signal handlers
    signal.signal(signal.SIGINT, solenoid.handle_exit)
    signal.signal(signal.SIGTERM, solenoid.handle_exit)

    try:
        solenoid.schedule_pulses()
    except Exception as e:
        print(f"Error: {e}")
        solenoid.handle_exit(None, None)

if __name__ == "__main__":
    main()

