import serial
import time
import signal
import re

class ESP8266:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        try:
            self.ser = serial.Serial(port=port, baudrate=baud_rate, timeout=timeout)
        except serial.SerialException as e:
            print(f"Failed to open serial port: {e}")
            exit(1)

        signal.signal(signal.SIGTERM, self._signal_handler)

    def _signal_handler(self, signal, frame):
        self.ser.close()
        exit(0)

    def _send_command(self, command, timeout=1.0):
        try:
            self.ser.write(f"{command}\r\n".encode())
            response = self.ser.read_until(b'\r\n', timeout=timeout)
            return response
        except serial.SerialException as e:
            print(f"Failed to send command: {e}")
            return None

    def test_connection(self):
        response = self._send_command('AT')
        return response == b'OK\r\n'

    def restart(self):
        self._send_command('AT+RST')
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid, password):
        response = self._send_command(f'AT+CWJAP="{ssid}","{password}"', timeout=10)
        return response == b'OK\r\n'

    def disconnect_wifi(self):
        response = self._send_command('AT+CWQAP')
        return response == b'OK\r\n'

    def get_ip(self):
        response = self._send_command('AT+CIFSR')
        match = re.search(r'STAIP:"(.*?)"', response.decode())
        return match.group(1) if match else None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        self._send_command(f'AT+CIPSTART="TCP","{host}",{port}')
        self._send_command(f'AT+CIPSEND={len(data)}')
        self.ser.write(data)
        return self.receive_http_response()

    def receive_http_response(self, timeout=5.0):
        response = self.ser.read_until(b'\r\n\r\n', timeout=timeout)
        if response.endswith(b'CLOSED\r\n'):
            return None
        return response

