class ESP8266:
    def __init__(self):
        try:
            self.ser = serial.Serial(
                port='/dev/serial0', 
                baudrate=115200, 
                timeout=5, 
                write_timeout=10, 
                inter_byte_timeout=0.5
            )
        except serial.SerialException as e:
            print(f"Error opening serial port: {e}")
            exit(1)

        signal.signal(signal.SIGTERM, self._signal_term_handler)

    def _signal_term_handler(self, signal, frame):
        print('Termination signal received. Cleaning up...')
        self.ser.close()
        exit(0)

    def _send_command(self, command, delay=1, max_retries=3):
        for i in range(max_retries):
            self.ser.write(f"{command}\r\n".encode())
            time.sleep(delay)
            response = self._read_response()
            if response:
                return response
        return None

    def _read_response(self):
        response = self.ser.read_until(b'\r\n').decode().strip()
        if 'OK' in response or 'ERROR' in response or 'FAIL' in response:
            return response
        return None

    def test_connection(self):
        return self._send_command("AT") == "OK"

    def restart(self):
        return self._send_command("AT+RST") == "OK"

    def connect_wifi(self, ssid, password):
        self._send_command(f"AT+CWJAP_CUR=\"{ssid}\",\"{password}\"")
        time.sleep(5)
        response = self._read_response()
        return 'WIFI GOT IP' in response

