import serial
import logging
import time

class SimpleGPS:
    def __init__(self):
        self.ser = None

    def connect(self):
        try:
            self.ser = serial.Serial('/dev/serial0', 9600, timeout=1)
            return True
        except OSError:
            logging.error("Failed to open UART port")
            return False

    def read_data(self):
        try:
            if self.ser and self.ser.in_waiting:
                line = self.ser.readline().decode('utf-8').strip()
                return line
        except (OSError, UnicodeDecodeError):
            logging.error("Failed to read or decode data")
        return None

    def parse_gga(self, line):
        if not line or not (line.startswith('$GPGGA') or line.startswith('$GNGGA')):
            return None

        try:
            _, utc_time, latitude, _, _, fix_quality, num_satellites, *_ = line.split(',')
            latitude = float(latitude) if latitude else None
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': None,  # Not provided in GGA sentence
                'fix_quality': fix_quality,
                'num_satellites': num_satellites,
            }
        except (IndexError, ValueError):
            logging.error("Failed to parse GGA sentence")
            return None

    def close(self):
        try:
            if self.ser:
                self.ser.close()
                self.ser = None
        except Exception as e:
            logging.error(f"Failed to close UART port: {e}")

if __name__ == "__main__":
