        if uart_port is None:
            uart_port = serial.Serial(UART_DEVICE, UART_BAUD, timeout=UART_TIMEOUT)
    finally:
        uart_lock.release()

def close_uart():
    global uart_port
    uart_lock.acquire()
    try:
        if uart_port is not None:
            uart_port.close()
            uart_port = None
    finally:
        uart_lock.release()

