import json

app = Flask(__name__)
api = Api(app)

# Initialize serial connection
ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)

# Initialize in-memory list
data = [{'id': 0, 'name': 'Item 1', 'done': False},
        {'id': 1, 'name': 'Item 2', 'done': False}]

def get_next_id():
    return max([item['id'] for item in data]) + 1

def get_item_by_id(item_id):
    for item in data:
        if item['id'] == item_id:
            return item
    return None

def update_item(item_id, name=None, done=None):
    item = get_item_by_id(item_id)
    if item is None:
        return None
    if name is not None:
        item['name'] = name
    if done is not None:
        item['done'] = done
    return item

def add_item(name, done):
    item_id = get_next_id()
    data.append({'id': item_id, 'name': name, 'done': done})
    return get_item_by_id(item_id)

class Version(Resource):
    def get(self):
        try:
            ser.write(b'*IDN?\n')
            time.sleep(0.1)
            response = ser.read_all().decode().replace('\n', '<br>')
            return {'response': response}, 200
        except Exception as e:
            return {'error': str(e)}, 503

class GetData(Resource):
    def get(self):
        return {'data': data}, 200

class GetSet(Resource):
    def get(self, item_id):
        item = get_item_by_id(item_id)
        if item is None:
            return {'error': 'Item not found'}, 404
        return item, 200

class GetPost(Resource):
